"""Client addresses (docs/ratelimit.md, section 7)."""

import ipaddress


def parse_address(text: str):
    """An address in one of the forms of section 7.3, or None. IPv4-mapped IPv6 gives the IPv4 address."""
    text = text.strip(" \t")
    if text.startswith("["):
        end = text.find("]")
        if end < 0:
            return None
        rest = text[end + 1:]
        if rest and not (rest[0] == ":" and rest[1:].isascii() and rest[1:].isdigit()):
            return None
        host = text[1:end]
        if ":" not in host:
            return None
    elif text.count(":") == 1:
        host, _, port = text.partition(":")
        if not (port.isascii() and port.isdigit()):
            return None
    else:
        host = text
    if "%" in host or not host.isascii():
        return None
    try:
        addr = ipaddress.ip_address(host)
    except ValueError:
        return None
    if addr.version == 6 and addr.ipv4_mapped is not None:
        return addr.ipv4_mapped
    return addr


def in_any(addr, networks) -> bool:
    return addr is not None and any(addr.version == n.version and addr in n for n in networks)


def client_address(request, trusted):
    """The client address of a request (section 7), or None when the peer is not an address."""
    peer = parse_address(request.peer)
    if not in_any(peer, trusted):
        return peer
    entries = []
    for value in request.headers.get_all("X-Forwarded-For"):
        entries.extend(e.strip(" \t") for e in value.split(","))
    if not entries:
        return peer
    previous = peer
    for entry in reversed(entries):
        addr = parse_address(entry)
        if addr is None:
            return previous
        if not in_any(addr, trusted):
            return addr
        previous = addr
    return previous


def key_text(addr) -> str:
    if addr.version == 4:
        return str(addr)
    return str(ipaddress.ip_network(f"{addr}/64", strict=False))
