"""Stage 3: rate limits (docs/ratelimit.md)."""

import math
from fractions import Fraction

from frontdoor.ratelimit.address import client_address, in_any, key_text
from frontdoor.ratelimit.state import new_state

NAME = "ratelimit"


class State:
    def __init__(self, config):
        self.limits = config.section("limit", [])
        self.trusted = config.section("clients", ())
        self.states = {}
        self.now = None
        self.limited = {lim.name: 0 for lim in self.limits}


def setup(config):
    return State(config)


def _key_value(part, ctx, addr):
    if part == "tenant":
        return ctx.tenant
    if part == "client":
        return key_text(addr)
    if part == "route":
        return ctx.route.name
    if part == "method":
        return ctx.request.method.upper()
    value = ctx.request.headers.get(part[len("header:"):])
    value = value.strip(" \t") if value is not None else None
    return value or None


def _covering(ctx, state, addr):
    out = []
    for lim in state.limits:
        if lim.routes is not None and ctx.route.name not in lim.routes:
            continue
        if lim.methods is not None and ctx.request.method.upper() not in lim.methods:
            continue
        if in_any(addr, lim.exempt):
            continue
        key = tuple(_key_value(p, ctx, addr) for p in lim.key)
        if any(v is None for v in key):
            continue
        out.append((lim, key))
    return out


def handle(ctx, state):
    if not state.limits:
        return None
    ts = ctx.request.ts_ms
    state.now = ts if state.now is None else max(state.now, ts)
    now = state.now
    addr = client_address(ctx.request, state.trusted)
    covering = _covering(ctx, state, addr)
    if not covering:
        return None
    method = ctx.request.method.upper()
    items = []
    for lim, key in covering:
        st = state.states.get((lim.name, key))
        if st is None:
            st = state.states[(lim.name, key)] = new_state(lim, now)
        st.refill(now)
        items.append((lim, st, lim.cost_of(method)))
    refusing = [(lim, st, c) for lim, st, c in items if c > lim.capacity or not st.allows(c)]
    if not refusing:
        for _, st, c in items:
            st.charge(c)
        lim, st, _ = min(items, key=lambda it: it[1].remaining())  # min is stable: first listed wins ties
        ctx.headers["RateLimit-Limit"] = str(lim.capacity)
        ctx.headers["RateLimit-Remaining"] = str(st.remaining())
        ctx.headers["RateLimit-Reset"] = str(st.reset(now))
        return None
    best = None
    for lim, st, c in refusing:
        state.limited[lim.name] += 1
        over = c > lim.capacity
        wait = st.wait(c, now)
        rank = (1, Fraction(0)) if over else (0, wait)
        if best is None or rank > best[0]:
            best = (rank, lim, st, over, wait)
    _, lim, st, over, wait = best
    ctx.headers["RateLimit-Limit"] = str(lim.capacity)
    ctx.headers["RateLimit-Remaining"] = str(st.remaining())
    ctx.headers["RateLimit-Reset"] = str(st.reset(now))
    if not over:
        ctx.headers["Retry-After"] = str(max(1, math.ceil(Fraction(wait) / 1000)))
    return 429


def summary(state):
    if not state.limits:
        return {}
    return {"limited": dict(state.limited)}
